const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const jfkAirport = ee.Geometry.Point([-73.78, 40.64]); // JFK Airport coordinates
    const targetDate = ee.Date('2025-06-24');
    const historicalStart = ee.Date('2020-06-01');
    const historicalEnd = ee.Date('2024-06-30');

    // MODIS LST Collection ID
    const modisCollection = 'MODIS/061/MOD11A1';
    const lstBand = 'LST_Day_1km';

    // Helper function for quality masking
    function maskLST(image) {
        const qc = image.select('QC_Day');
        // Bits 0-1 are mandatory quality flags. '00' indicates good quality.
        const qualityMask = qc.bitwiseAnd(0b11).eq(0);
        return image.updateMask(qualityMask).select(lstBand);
    }

    // Helper function to extract temperature
    function getTemperature(image, geom) {
        const temp = image.multiply(0.02).subtract(273.15); // Scale and convert from Kelvin to Celsius
        const stats = temp.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: geom,
            scale: 1000,
            maxPixels: 1e9
        });
        return stats.get(lstBand);
    }

    // 2. Data Acquisition & Check
    // Target day
    const targetCollection = ee.ImageCollection(modisCollection)
        .filterDate(targetDate, targetDate.advance(1, 'day'))
        .map(maskLST);

    // Historical period
    const historicalCollection = ee.ImageCollection(modisCollection)
        .filterDate(historicalStart, historicalEnd)
        .filter(ee.Filter.calendarRange(6, 6, 'month')) // Ensure only June images
        .map(maskLST);

    const targetCollectionSize = targetCollection.size().getInfo();
    const historicalCollectionSize = historicalCollection.size().getInfo();

    if (targetCollectionSize === 0 || historicalCollectionSize === 0) {
        console.log(`Target day image count: ${targetCollectionSize}`);
        console.log(`Historical period image count: ${historicalCollectionSize}`);
        console.log("Evidence: No images found for the target day or the historical period.");
        console.log("A: Yes");
        return;
    }
    console.log(`Image Count (Target): ${targetCollectionSize}`);
    console.log(`Image Count (Historical): ${historicalCollectionSize}`);


    // 3. Processing
    const targetImage = ee.Image(targetCollection.first());
    const historicalMaxImage = historicalCollection.max(); // Get the max LST value for each pixel over the period

    // 4. Calculation
    const targetTemp ee.Number(getTemperature(targetImage, jfkAirport));
    const historicalMaxTemp = ee.Number(getTemperature(historicalMaxImage, jfkAirport));

    const targetTempVal = targetTemp.getInfo();
    const historicalMaxTempVal = historicalMaxTemp.getInfo();

    if (targetTempVal === null || historicalMaxTempVal === null) {
        console.log(`Target Temp (C): ${targetTempVal}`);
        console.log(`Historical Max Temp (C): ${historicalMaxTempVal}`);
        console.log("Evidence: Could not extract a valid temperature value, likely due to cloud cover.");
        console.log("A: Yes");
        return;
    }

    // 5. Validation & Final Answer
    console.log(`JFK Temperature on 2025-06-24: ${targetTempVal.toFixed(2)} C`);
    console.log(`Highest June Temperature (2020-2024): ${historicalMaxTempVal.toFixed(2)} C`);

    if (targetTempVal > historicalMaxTempVal) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("An error occurred during Earth Engine initialization or analysis.");
        console.error(e);
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
    }
}

initEE();
